CREATE TABLE IF NOT EXISTS employee_performance_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE, review_period text NOT NULL, reviewer_employee_id uuid REFERENCES workforce_employees(id), rating numeric(4,2), goals text, achievements text, development_plan text, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());